CREATE SCHEMA "app";

CREATE SCHEMA "other";

CREATE TYPE "app"."status" AS ENUM (
  'active',
  'on hold'
);

CREATE TYPE "status" AS ENUM (
  'a',
  'b'
);

CREATE TABLE "app"."users" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "st" app.status NOT NULL,
  "st2" status,
  "cur" public.money_t,
  "cur2" "other"."money_t",
  "name" varchar DEFAULT 'x'
);

CREATE TABLE "posts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int,
  "t" timestamp with time zone DEFAULT (now())
);

CREATE TABLE "other"."tags" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" "My Type"
);

COMMENT ON TABLE "app"."users" IS 'It''s users';

COMMENT ON COLUMN "app"."users"."name" IS 'Bob''s name';

COMMENT ON TABLE "posts" IS 'posts';

ALTER TABLE "posts" ADD FOREIGN KEY ("user_id") REFERENCES "app"."users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

CREATE TABLE "app"."users_tags" (
  "users_id" int,
  "tags_id" smallint,
  PRIMARY KEY ("users_id", "tags_id")
);

ALTER TABLE "app"."users_tags" ADD FOREIGN KEY ("users_id") REFERENCES "app"."users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "app"."users_tags" ADD FOREIGN KEY ("tags_id") REFERENCES "other"."tags" ("id") DEFERRABLE INITIALLY IMMEDIATE;


CREATE TABLE "posts_tags" (
  "posts_id" bigint,
  "tags_id" smallint,
  PRIMARY KEY ("posts_id", "tags_id")
);

ALTER TABLE "posts_tags" ADD FOREIGN KEY ("posts_id") REFERENCES "posts" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "posts_tags" ADD FOREIGN KEY ("tags_id") REFERENCES "other"."tags" ("id") DEFERRABLE INITIALLY IMMEDIATE;


ALTER TABLE "other"."tags" ADD CONSTRAINT "r1" FOREIGN KEY ("id") REFERENCES "posts" ("user_id") ON DELETE CASCADE ON UPDATE SET NULL DEFERRABLE INITIALLY IMMEDIATE;
